const LOAD_FACTOR_NUMERATOR: usize = 7;
const LOAD_FACTOR_DENOMINATOR: usize = 8;

#[derive(Debug, Clone)]
pub struct HopscotchMap<K, V> {
    entries: Vec<(K, V)>,
    bucket_count: usize,
}

impl<K, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self {
            entries: Vec::new(),
            bucket_count: 0,
        }
    }
}

impl<K: Eq, V> HopscotchMap<K, V> {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn reserve(&mut self, count: i32) {
        self.bucket_count = if count <= 0 {
            0
        } else {
            required_bucket_count(count as usize)
        };
    }

    pub fn insert(&mut self, entry: (K, V)) {
        let (key, value) = entry;

        if let Some((_, existing_value)) = self
            .entries
            .iter_mut()
            .find(|(existing_key, _)| *existing_key == key)
        {
            *existing_value = value;
            return;
        }

        let next_len = self.entries.len() + 1;
        let required = required_bucket_count(next_len);
        if required > self.bucket_count {
            self.bucket_count = required;
        }

        self.entries.push((key, value));
    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }

    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    pub fn overflow_size(&self) -> usize {
        0
    }
}

fn required_bucket_count(count: usize) -> usize {
    if count == 0 {
        return 0;
    }

    let minimum_buckets =
        (count * LOAD_FACTOR_DENOMINATOR).div_ceil(LOAD_FACTOR_NUMERATOR);
    minimum_buckets.next_power_of_two()
}

#[cfg(test)]
mod tests {
    use super::{required_bucket_count, HopscotchMap};

    #[test]
    fn reserve_matches_observed_bucket_sizes() {
        let expected = [
            (0, 0),
            (1, 2),
            (2, 4),
            (3, 4),
            (4, 8),
            (5, 8),
            (8, 16),
            (14, 16),
            (15, 32),
            (28, 32),
            (29, 64),
            (57, 64),
            (58, 128),
        ];

        for (count, buckets) in expected {
            assert_eq!(required_bucket_count(count), buckets);
        }
    }

    #[test]
    fn insert_updates_existing_keys() {
        let mut map = HopscotchMap::new();
        map.insert((1, 10));
        map.insert((1, 20));

        assert_eq!(map.size(), 1);
        assert_eq!(map.overflow_size(), 0);
    }
}

