    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }

    pub fn bucket_count(&self) -> u64 {
        self.bucket_count
    }

    pub fn overflow_size(&self) -> usize {
        0
    }
}

impl<K, V> Default for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    fn default() -> Self {
        Self::new()
    }
