fn bucket_count_for_requested(count: i32) -> u64 {
    if count <= 0 {
        0
    } else {
        bucket_count_for_size(count as u64)
    }
}

fn bucket_count_for_size(count: u64) -> u64 {
    let mut buckets = 2_u64;

    while max_entries_for_buckets(buckets) < count {
        buckets = buckets.checked_mul(2).expect("bucket count overflow");
    }

    buckets
}

fn max_entries_for_buckets(bucket_count: u64) -> u64 {
    bucket_count.saturating_mul(9) / 10
